    return 1 <= day <= 28 and 1 <= month <= 12 and 1801 <= year <= 2199

def post(day, month, year, result):
    # Helper function to compute the correct answer independently
    def gregorian_weekday(day, month, year):
        if month < 3:
            month += 12
            year -= 1
        k = year % 100
        j = year // 100
        return (day + 13 * (month + 1) // 5 + k + k // 4 + j // 4 + 5 * j) % 7

    # Check if the result is within the valid range of day of week
    return 0 <= result <= 6 and result == gregorian_weekday(day, month, year)
